import{_t as e,it as t,n,rt as r}from"./chunks/framework.XJu5filh.js";var i=JSON.parse(`{"title":"简介","description":"","frontmatter":{},"headers":[],"relativePath":"begin/about.md","filePath":"begin/about.md","lastUpdated":1792924908000}`),a={name:`begin/about.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to “简介”">​</a></h1><h2 id="什么是太郎" tabindex="-1">什么是太郎？ <a class="header-anchor" href="#什么是太郎" aria-label="Permalink to “什么是太郎？”">​</a></h2><p>太郎是一款服务于碧蓝幻想玩家的辅助客户端，提供 Chrome 扩展、Windows 桌面端、macOS 桌面端和 Android 移动端，帮助玩家查看游戏数据、管理队伍配置和分析战斗记录。</p><p>扩展通过浏览器侧边栏展示信息；桌面端提供内嵌游戏页面、书签和功能区；Android 通过游戏中的工具栏打开功能面板。各端共享主要业务功能，具体使用方式见<a href="./start">快速开始</a>。</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>碧蓝幻想，简称gbf，日本知名游戏公司Cygames开发的一款幻想系角色扮演类网页游戏。</p></div><h2 id="数据是怎么来的" tabindex="-1">数据是怎么来的？ <a class="header-anchor" href="#数据是怎么来的" aria-label="Permalink to “数据是怎么来的？”">​</a></h2><p>数据来自游戏页面的网络请求与响应。太郎通过页面监听脚本或客户端的浏览能力获取这些数据，交给各端共用的解析模块分析处理，再展示在功能面板中。</p><h2 id="使用安全吗" tabindex="-1">使用安全吗？ <a class="header-anchor" href="#使用安全吗" aria-label="Permalink to “使用安全吗？”">​</a></h2><p>游戏规则及第三方工具的认定由游戏官方决定，使用前请自行了解相关规则。太郎通过游戏响应展示和分析数据，账号登录、游戏操作仍由用户自行完成。</p>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};